import React from 'react';
import './App.css';
import Shell from './Shell';
import CharacterLoader from './CharacterLoader';

function App() {
  return (
    <Shell
      titulo="Carga los personajes cuando tú quieras"
      descripcion="La petición a la API se ejecuta solo al pulsar el botón, mostrando el estado de carga mientras llegan los datos."
    >
      <CharacterLoader />
    </Shell>
  );
}

export default App;
